import {node} from './experience.js';
let connection;function db(){return connection??=new Promise((resolve,reject)=>{const request=indexedDB.open('capimimo-gifts-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('gifts',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function store(action,value){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction('gifts',action==='all'?'readonly':'readwrite'),table=tx.objectStore('gifts'),request=action==='all'?table.getAll():action==='put'?table.put(value):table.delete(value);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
export async function getSavedGift(id){return(await store('all')).find(gift=>gift.id===id);}
export async function putSavedGift(gift){return store('put',gift);}
export function initGiftLibrary({capture,restore,toast,isIncoming,onPreview,onDownload,onImport}){
 const dialog=node('dialog','gift-library-dialog');dialog.setAttribute('aria-labelledby','gift-library-title');dialog.innerHTML='<button type="button" class="library-close" aria-label="Fechar meus presentes">×</button><h2 id="gift-library-title">Meus presentes</h2><p>Guardados neste navegador, com as fotos e os áudios. Não são publicados.</p><label class="library-import-label">Importar uma resposta<input type="file" accept="application/json,.json" multiple class="library-response-import"></label><div class="gift-library-list"></div><p class="library-status" role="status"></p>';document.body.append(dialog);const status=dialog.querySelector('.library-status'),list=dialog.querySelector('.gift-library-list');let busy=false,renderVersion=0;
 const controls=node('div','library-controls');controls.innerHTML='<button type="button" class="save-my-gift">Guardar este presente</button><button type="button" class="open-my-gifts">Meus presentes</button>';document.querySelector('.draft-status').before(controls);
 async function render(){const own=++renderVersion;list.replaceChildren();const rows=(await store('all')).sort((a,b)=>b.updatedAt-a.updatedAt);if(own!==renderVersion||!dialog.open)return;if(!rows.length)list.append(node('p','','Você ainda não guardou um presente. Use “Guardar este presente” no criador.'));for(const gift of rows){const row=node('article','saved-gift');const gallery=Array.isArray(gift.media?.gallery)?gift.media.gallery:[],thumbnail=gallery.find(photo=>photo?.id===gift.media?.selected&&photo.src)||gallery.find(photo=>photo?.src);if(thumbnail){const image=node('img');image.src=thumbnail.src;image.alt='';row.append(image);}const info=node('div');row.dataset.giftId=gift.id;info.append(node('strong','',gift.state.recipient||'Um mimo sem nome'),node('p','',new Date(gift.updatedAt).toLocaleDateString('pt-BR')+' · '+({stories:'Stories',livro:'Livro',cartao:'Cartão',convite:'Convite'}[gift.state.format]||'Presente')+' · '+(gift.state.replies?.length||0)+' '+((gift.state.replies?.length||0)===1?'resposta':'respostas')));const edit=node('button','','Abrir para editar'),duplicate=node('button','','Criar uma cópia'),remove=node('button','','Excluir');duplicate.type='button';duplicate.addEventListener('click',async()=>{if(busy||!confirm('Criar uma cópia para editar? Guarde primeiro as alterações do rascunho atual se quiser mantê-las.'))return;busy=true;try{const copy=structuredClone(gift),id=crypto.randomUUID();copy.id=id;copy.state.draftId=id;delete copy.state.purchaseId;copy.state.replies=[];copy.state.guests=(copy.state.guests||[]).map(guest=>({...guest,status:'invited',attendingCount:0}));await restore(copy);dialog.close();document.querySelector('#atelier').scrollIntoView({behavior:'instant'});toast('Uma cópia pronta para personalizar. O original continua na biblioteca.');}catch{status.textContent='Não foi possível criar a cópia agora.';}finally{busy=false;}});edit.type=remove.type='button';edit.addEventListener('click',async()=>{if(busy)return;if(!confirm('Abrir este presente? O rascunho atual será substituído. Guarde-o primeiro se quiser manter os dois.'))return;busy=true;edit.disabled=true;try{await restore(gift);dialog.close();document.querySelector('#atelier').scrollIntoView({behavior:'instant'});toast('Presente aberto com suas fotos e seu áudio.');}catch{status.textContent='Não foi possível abrir o presente. Tente novamente.';}finally{busy=false;edit.disabled=false;}});remove.addEventListener('click',async()=>{if(busy||!confirm('Excluir este presente da biblioteca? A cópia baixada continua com você.'))return;await store('delete',gift.id);await render();});const view=node('button','','Ver presente'),download=node('button','','Baixar presente');view.type=download.type='button';view.className='view-saved-gift';download.className='download-saved-gift';view.addEventListener('click',async()=>{dialog.close();try{await onPreview(gift);}catch{toast('Não foi possível abrir este presente.');}});download.addEventListener('click',async()=>{if(busy)return;busy=true;download.disabled=true;try{if(await onDownload(gift)===true)status.textContent='Presente baixado. Envie o arquivo para quem vai receber.';else status.textContent='Download não realizado. Confira o acesso à compra para baixar este presente.';}catch{status.textContent='Não foi possível baixar este presente agora.';}finally{busy=false;download.disabled=false;}});info.append(view,edit,download,duplicate,remove);row.append(info);list.append(row);}}
 controls.querySelector('.save-my-gift').addEventListener('click',async event=>{if(isIncoming()){toast('Abra seu próprio rascunho para guardar um presente.');return;}event.target.disabled=true;try{const gift=await capture(),rows=await store('all');if(rows.length>=20&&!rows.some(row=>row.id===gift.id)){toast('Sua biblioteca tem 20 presentes. Exclua um para guardar outro.');return;}await store('put',{...gift,updatedAt:Date.now()});toast('Presente guardado com fotos e áudio neste navegador.');}catch{toast('O navegador não permitiu guardar. Baixe uma cópia do presente para conservar.');}finally{event.target.disabled=false;}});
 async function open(){status.textContent='';dialog.showModal();const own=renderVersion+1;try{await render();}catch{if(own!==renderVersion||!dialog.open)return;status.textContent='Este navegador não disponibilizou a biblioteca local.';}}
 const headerButton=node('button','header-library-button','Meus presentes');headerButton.type='button';document.querySelector('.announcement').append(headerButton);headerButton.addEventListener('click',open);dialog.querySelector('.library-response-import').addEventListener('change',async event=>{await onImport([...event.target.files]);event.target.value='';await render();});controls.querySelector('.open-my-gifts').addEventListener('click',open);dialog.addEventListener('close',()=>{if(!dialog.open)renderVersion++;});dialog.querySelector('.library-close').addEventListener('click',()=>dialog.close());return {open,restore};
}
